import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.DoCD98hS.js";const s=JSON.parse('{"title":"H5 模板 · Vant、Tailwind 与 Nuxt","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/h5.md","filePath":"modules/catalog/h5.md","lastUpdated":1795624668000}'),n={name:"modules/catalog/h5.md"};function i(r,t,l,h,c,u){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="h5-模板-·-vant、tailwind-与-nuxt" tabindex="-1">H5 模板 · Vant、Tailwind 与 Nuxt <a class="header-anchor" href="#h5-模板-·-vant、tailwind-与-nuxt" aria-label="Permalink to &quot;H5 模板 · Vant、Tailwind 与 Nuxt&quot;">​</a></h1><p>五个 Vue 3 移动端应用起点，覆盖 Nuxt SSR、Tailwind px-to-viewport、UnoCSS mobile-forever、PWA、多 UI 库单选与旧浏览器兼容。它们和 PC 模板使用同一套产物目录与演示地址规律：<code>&lt;包名&gt;/dist/index.html</code>。</p><p>第六个 H5 模板 <code>tpl-vue3-h5-vite-vant-unocss-forever-fanh5</code> 与 Fm 移动端组件一起归在 <a href="./fanh5.html">Fantastic Mobile 专题</a>，不重复列在这张表里。</p><h2 id="模板一览" tabindex="-1">模板一览 <a class="header-anchor" href="#模板一览" aria-label="Permalink to &quot;模板一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板</th><th>技术栈</th><th>适合</th><th>在线演示</th></tr></thead><tbody><tr><td><code>tpl-vue3-h5-nuxt-vant-unocss-forever-nvm</code></td><td>Nuxt 4 SSR、Vant、UnoCSS、Pinia、i18n</td><td>需要服务端渲染、Nuxt 文件路由或多语言能力的移动端项目</td><td>暂未提供</td></tr><tr><td><code>tpl-vue3-h5-vite-vant-tailwind-px2vw-yvht</code></td><td>Vue 3、Vite、Vant 4、Tailwind 4、Pinia</td><td>希望用 Tailwind 原子类和 px-to-viewport 适配的 H5 项目</td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-h5-vite-vant-tailwind-px2vw-yvht/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-vue3-h5-vite-vant-unocss-forever-mob</code></td><td>Vue 3、Vite、TypeScript、Vant、UnoCSS、Pinia</td><td>需要 mobile-forever 设计口径、legacy 兼容与完整移动端骨架</td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-h5-vite-vant-unocss-forever-mob/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-vue3-h5-vite-vant-unocss-forever-vvm</code></td><td>Vue 3、Vite、Vant、UnoCSS、Pinia、PWA</td><td>需要 PWA、状态持久化、文件路由与移动端常用能力</td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-h5-vite-vant-unocss-forever-vvm/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-vue3-h5-vite-mixed-vant-nut-varlet-svht</code></td><td>Vue 3.5、Vite 8、Vant / NutUI / Varlet、Pinia、PWA</td><td>需要多 UI 库构建期单选、完整请求层与业务页面骨架</td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-h5-vite-mixed-vant-nut-varlet-svht/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><h2 id="模板说明" tabindex="-1">模板说明 <a class="header-anchor" href="#模板说明" aria-label="Permalink to &quot;模板说明&quot;">​</a></h2><h3 id="nuxt-vant" tabindex="-1">Nuxt Vant <a class="header-anchor" href="#nuxt-vant" aria-label="Permalink to &quot;Nuxt Vant&quot;">​</a></h3><p><code>tpl-vue3-h5-nuxt-vant-unocss-forever-nvm</code> 使用 Nuxt 4 的文件路由、布局和 SSR 能力，配合 Vant 与 UnoCSS 完成移动端页面。适合已有 Nuxt 服务端、需要多语言或希望保留 SSR 的项目。</p><h3 id="tailwind-px2vw" tabindex="-1">Tailwind px2vw <a class="header-anchor" href="#tailwind-px2vw" aria-label="Permalink to &quot;Tailwind px2vw&quot;">​</a></h3><p><code>tpl-vue3-h5-vite-vant-tailwind-px2vw-yvht</code> 以 Vite 为构建入口，Tailwind 负责原子类，Vant 负责移动端交互组件。设计稿按 px 标注时，可直接沿用模板的视口换算配置。</p><h3 id="mobvue" tabindex="-1">MobVue <a class="header-anchor" href="#mobvue" aria-label="Permalink to &quot;MobVue&quot;">​</a></h3><p><code>tpl-vue3-h5-vite-vant-unocss-forever-mob</code> 采用 mobile-forever 的移动端设计口径，保留 legacy 兼容配置。适合需要成熟 H5 骨架、又希望沿用 UnoCSS 的团队。</p><h3 id="多-ui-库混用" tabindex="-1">多 UI 库混用 <a class="header-anchor" href="#多-ui-库混用" aria-label="Permalink to &quot;多 UI 库混用&quot;">​</a></h3><p><code>tpl-vue3-h5-vite-mixed-vant-nut-varlet-svht</code> 在 Vant、NutUI、Varlet 之间做构建期单选，不把三套 UI 同时放进生产包；同时提供类型安全请求、TanStack Query、PWA 与完整商城示例。</p><h3 id="vue3-vant-mobile" tabindex="-1">Vue3 Vant Mobile <a class="header-anchor" href="#vue3-vant-mobile" aria-label="Permalink to &quot;Vue3 Vant Mobile&quot;">​</a></h3><p><code>tpl-vue3-h5-vite-vant-unocss-forever-vvm</code> 在 Vant 与 UnoCSS 基础上加入 PWA、Pinia 持久化和文件路由，适合需要离线入口、应用式移动页面或更完整默认能力的项目。</p><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><ul><li>需要 SSR、服务端数据编排或 Nuxt 生态模块时，选 <code>nvm</code>。</li><li>团队已经使用 Tailwind，并希望按设计稿宽度做视口换算时，选 <code>yvht</code>。</li><li>需要一套带 legacy 兼容与 mobile-forever 约定的 Vant + UnoCSS 骨架时，选 <code>mob</code>。</li><li>需要 PWA、离线能力或更完整的移动端默认能力时，选 <code>vvm</code>。</li><li>需要在 Vant、NutUI、Varlet 之间按项目切换，或需要更完整的请求与业务页面骨架时，选 <code>svht</code>。</li></ul><p>有演示链接的模板可直接用移动视口体验首页、组件示例与路由，再决定改造哪一套。</p><h2 id="与-pc-模板一致的产物规律" tabindex="-1">与 PC 模板一致的产物规律 <a class="header-anchor" href="#与-pc-模板一致的产物规律" aria-label="Permalink to &quot;与 PC 模板一致的产物规律&quot;">​</a></h2><p>H5 模板和后台、可视化模板一样，构建产物落在包目录下的 <code>dist/</code>，入口是 <code>dist/index.html</code>。演示地址按包名定位，不在包名之外再包一层产品目录。</p><p>部署到子路径时，Vite 模板通过 <code>VITE_PUBLIC_PATH</code> 设置资源前缀，Nuxt 模板通过 <code>NUXT_APP_BASE_URL</code> 设置；构建后 HTML 中的 JS、CSS 和图标路径都应带上同一个前缀。</p><h2 id="上游与许可" tabindex="-1">上游与许可 <a class="header-anchor" href="#上游与许可" aria-label="Permalink to &quot;上游与许可&quot;">​</a></h2><p>四个模板分别提取自对应的 MIT 上游项目，业务代码、配置与依赖保持上游结构；归档只改写包名与元信息。二次开发时优先保留上游目录约定，再按自己的业务替换页面和接口。</p>',24)])])}const p=e(n,[["render",i]]);export{s as __pageData,p as default};
